uv run python -c "import numpy as np, pandas as pd; train=pd.read_csv('train.csv'); feat=[c for c in train.columns if c not in ('entity_id','target')]; X=train[feat].to_numpy(float).reshape(-1,4,len(feat)); y=train['target'].to_numpy(float).reshape(-1,4); rmse_mean=[]; rmse_nn=[]; rmse_idw=[]; 
for Xe,ye in zip(X,y):
 d=((Xe[:,None,:]-Xe[None,:,:])**2).sum(axis=2)
 for i in range(4):
  mask=np.arange(4)!=i; others=ye[mask]; dist=d[i,mask]; rmse_mean.append((ye[i]-others.mean())**2); rmse_nn.append((ye[i]-others[np.argmin(dist)])**2); w=1/(dist+1e-9); pred=(w*others).sum()/w.sum(); rmse_idw.append((ye[i]-pred)**2)
print('loo_entity_mean_rmse', float(np.sqrt(np.mean(rmse_mean)))); print('loo_entity_nn_rmse', float(np.sqrt(np.mean(rmse_nn)))); print('loo_entity_idw_rmse', float(np.sqrt(np.mean(rmse_idw))))"

uv run python -c "import numpy as np, pandas as pd; train=pd.read_csv('train.csv'); feat=[c for c in train.columns if c not in ('entity_id','target')]; X=train[feat].to_numpy(float).reshape(-1,4,len(feat)); y=train['target'].to_numpy(float).reshape(-1,4);
for temp in [0.1,0.3,1.0,3.0,10.0]:
 errs=[]
 for Xe,ye in zip(X,y):
  d=((Xe[:,None,:]-Xe[None,:,:])**2).sum(axis=2)
  for i in range(4):
   mask=np.arange(4)!=i; dist=d[i,mask]; others=ye[mask]; w=np.exp(-dist/temp); pred=(w*others).sum()/w.sum(); errs.append((ye[i]-pred)**2)
 print(temp, float(np.sqrt(np.mean(errs))))"
